def main(xs, x):
    for i, v in enumerate(xs):
        if v == x:
            return i
    return -1

longest-run:
def main(xs):
    if not xs:
        return 0
    best = 1
    cur = 1
    for i in range(1, len(xs)):
        if xs[i] == xs[i - 1]:
            cur += 1
        else:
            cur = 1
        if cur > best:
            best = cur
    return best

has-pair-sum:
def main(xs, target):
    seen = set()
    for x in xs:
        if (target - x) in seen:
            return True
        seen.add(x)
    return False

digits:
def main(n):
    if n == 0:
        return [0]
    result = []
    while n > 0:
        result.append(n % 10)
        n //= 10
    return list(reversed(result))

primes-up-to:
def main(n):
    if n < 2:
        return []
    sieve = [True] * (n + 1)
    sieve[0] = False
    sieve[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False
    return [i for i, is_prime in enumerate(sieve) if is_prime]

histogram:
def main(xs, k):
    counts = [0] * k
    for x in xs:
        counts[x] += 1
    return counts

ledger:
def main(start, txs):
    balance = start
    rejected = 0
    for t in txs:
        if balance + t < 0:
            rejected += 1
        else:
            balance += t
    return (balance, rejected)
